const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mahajanga = ee.Geometry.Point([46.3167, -15.7167]); // Mahajanga, Madagascar
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';

  // 2. Data Acquisition - CHIRPS daily precipitation
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(mahajanga);

  const collectionSize = chirps.size().getInfo();
  console.log(`January 2020 images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate total rainfall
  const totalPrecip = chirps.sum();

  // Check valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mahajanga,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get total rainfall in mm and convert to inches
  const totalRainfallMm = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mahajanga,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Total rainfall (mm): ${totalRainfallMm?.toFixed(2) || 'null'}`);

  // 5. Validation & Final Answer
  if (totalRainfallMm === null || totalRainfallMm === undefined || isNaN(totalRainfallMm)) {
    console.log("<answer>C3</answer>");
    return;
  }

  const totalRainfallInches = totalRainfallMm / 25.4;
  console.log(`Total rainfall (inches): ${totalRainfallInches.toFixed(2)}`);
  console.log(`Threshold: 12 inches`);

  if (totalRainfallInches > 12) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
